public class ClassLoaderDemo {
    static {
        System.out.println("Initialization phase: Static block executed.");
    }

    public static void main(String[] args) throws ClassNotFoundException {
        // Loading and Linking happen here, but Initialization is deferred until usage
        Class<?> clazz = Class.forName("ClassLoaderDemo", false, ClassLoaderDemo.class.getClassLoader());
        System.out.println("Class loaded, but not initialized yet.");

        // Explicitly triggering initialization
        Class.forName("ClassLoaderDemo");
    }
}
